mapper.select:
SELECT 
FROM pad_info p
LEFT JOIN shelf_layer sl ON p.shelf_layer_code = sl.layer_code
LEFT JOIN pad_borrow_record br ON br.pad_id = p.id AND br.status = 'BORROWED'


        AND p.pad_code LIKE CONCAT('%', #{query.padCode}, '%')


        AND p.mold_type LIKE CONCAT('%', #{query.moldType}, '%')


        AND p.shelf_layer_code = #{query.shelfLayerCode}


        AND sl.shelf_code = #{query.shelfCode}


        AND p.maintenance_status = #{query.maintenanceStatus}


        AND p.stock_status = #{query.stockStatus}


ORDER BY p.create_time DESC

SELECT FROM pad_info p LEFT JOIN shelf_layer sl ON p.shelf_layer_code = sl.layer_code LEFT JOIN pad_borrow_record br ON br.pad_id = p.id AND br.status = 'BORROWED' WHERE p.id IN
#{id}
ORDER BY p.pad_code ASC
